CREATE TABLE pipeline_catalog(pipeline_key VARCHAR(60) PRIMARY KEY,databricks_job_id BIGINT NOT NULL,owner VARCHAR(80) NOT NULL,allowed_parameters VARCHAR(40)[] NOT NULL,base_cost NUMERIC(12,2) NOT NULL,approval_threshold NUMERIC(12,2) NOT NULL,sla_minutes INTEGER NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
INSERT INTO pipeline_catalog VALUES ('sales-bronze-gold',11223344,'data-platform',ARRAY['source_date','full_refresh','fail_quality','simulate_rate_limit'],40.00,75.00,30,true),('customer-360',22334455,'analytics',ARRAY['source_date','full_refresh','fail_quality','simulate_rate_limit'],55.00,100.00,45,true);
CREATE TABLE pipeline_execution(id UUID PRIMARY KEY,pipeline_key VARCHAR(60) NOT NULL REFERENCES pipeline_catalog,requested_by VARCHAR(80) NOT NULL,parameters JSONB NOT NULL,estimated_cost NUMERIC(12,2) NOT NULL,status VARCHAR(30) NOT NULL,databricks_run_id BIGINT,result_state VARCHAR(30),error_message VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_execution_poll ON pipeline_execution(status,updated_at);
CREATE TABLE quality_result(id BIGSERIAL PRIMARY KEY,execution_id UUID NOT NULL REFERENCES pipeline_execution,passed BOOLEAN NOT NULL,checks_passed INTEGER NOT NULL,checks_failed INTEGER NOT NULL,detail VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE quality_incident(id UUID PRIMARY KEY,execution_id UUID NOT NULL REFERENCES pipeline_execution,severity VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,detail VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_event(id UUID PRIMARY KEY,execution_id UUID NOT NULL REFERENCES pipeline_execution,actor VARCHAR(80) NOT NULL,action VARCHAR(60) NOT NULL,detail VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_execution ON audit_event(execution_id,created_at);
